-- ============================================================
-- SEED EXT 2: Módulo 06 — Be Going To (exercícios 71-175)
-- Novos tópicos: present continuous for future, was going to
-- (unfulfilled plans), future in the past, academic/TOEFL
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'be-going-to';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo be-going-to não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 11: present continuous for future arrangements
  (cid,11,71,'gap_fill','She ___ (present) her thesis to the committee next Thursday. (arranged appointment)','is presenting',NULL,'Present continuous = fixed future arrangement (like going to, but emphasizes scheduling).','medium'),
  (cid,11,72,'multiple_choice','Which sentence uses Present Continuous for a FUTURE ARRANGEMENT?','I''m meeting my supervisor at 10 a.m. tomorrow.','["I''m meeting my supervisor right now.","I meet my supervisor at 10 a.m. tomorrow.","I''m meeting my supervisor at 10 a.m. tomorrow.","I will be meeting my supervisor at 10 a.m. (future continuous — also OK)."]','Present continuous + future time marker = fixed future plan.','medium'),
  (cid,11,73,'gap_fill','They ___ (fly) to Geneva for the international symposium on Monday. (pre-booked)','are flying',NULL,'Present continuous for arranged future travel.','easy'),
  (cid,11,74,'multiple_choice','What is the DIFFERENCE between "I''m going to meet him" and "I''m meeting him"?','Both mean a planned future event; ''meeting'' implies a specific scheduled appointment.','["There is no difference at all","I''m going to meet is more formal","Both mean a planned future event; ''meeting'' implies a specific scheduled appointment.","I''m meeting him means it''s happening right now"]','Both express planned future, but present continuous often implies a timetabled/booked event.','hard'),
  (cid,11,75,'gap_fill','The department ___ (launch) its new online platform next semester. (scheduled institutional event)','is launching',NULL,'Present continuous for future institutional/organizational plans.','medium'),
  (cid,11,76,'multiple_choice','Which sentence is NOT appropriate for describing a future arrangement with present continuous?','The sun is rising tomorrow at 6:12 a.m.','["We''re announcing the results at the press conference next week.","I''m defending my dissertation on Friday.","The committee is meeting on Tuesday to discuss the proposals.","The sun is rising tomorrow at 6:12 a.m."]','"The sun rising" is a natural event — not an arrangement. Use "will rise."','hard'),
  (cid,11,77,'gap_fill','A: "Are you busy next week?" B: "Yes — I ___ (attend) three conferences back-to-back."','am attending',NULL,'Present continuous for confirmed future schedule.','easy'),

  -- BLOCK 12: was going to — unfulfilled past plans
  (cid,12,78,'gap_fill','I ___ (go/past plan) to the conference, but my flight was cancelled.','was going to go',NULL,'"Was/were going to" = a plan that existed in the past but was NOT carried out.','medium'),
  (cid,12,79,'multiple_choice','What does "She was going to publish her findings last year" mean?','She planned to publish but did not do so.','["She published last year as planned","She is planning to publish this year","She planned to publish but did not do so.","She had already published the year before"]','"Was going to" = unfulfilled past intention.','medium'),
  (cid,12,80,'gap_fill','They ___ (submit) the grant proposal, but the lead researcher fell ill.','were going to submit',NULL,'"Were going to submit" = planned but didn''t happen because of an obstacle.','medium'),
  (cid,12,81,'multiple_choice','Which sentence uses "was going to" correctly for an UNFULFILLED PLAN?','The team was going to replicate the study, but funding was withdrawn.','["The team was going to replicate the study and they did.","The team was going to replicate the study, but funding was withdrawn.","The team is going to replicate the study next year.","The team has been going to replicate the study."]','"Was going to X, but [obstacle]" = classic pattern for unfulfilled past plan.','medium'),
  (cid,12,82,'gap_fill','He ___ (apply) for the position, but he realized he didn''t meet the requirements.','was going to apply',NULL,'Past intention that was abandoned before action.','medium'),
  (cid,12,83,'multiple_choice','What is the difference between "She was going to submit" and "She didn''t submit"?','Was going to submit emphasizes there was a prior plan/intention that failed.','["They are identical in meaning","Was going to submit is more formal","Was going to submit emphasizes there was a prior plan/intention that failed.","She didn''t submit implies she never intended to"]','Was going to = prior intention + unfulfillment. Didn''t submit = just the act.','hard'),
  (cid,12,84,'gap_fill','We ___ (hold) the seminar outdoors, but the weather forecast was terrible.','were going to hold',NULL,'"Were going to hold" but the plan changed due to weather.','easy'),

  -- BLOCK 13: future in the past (was/were going to / would / was about to)
  (cid,13,85,'multiple_choice','In the sentence "She knew the exam was going to be difficult," what does "was going to be" express?','A future prediction from the perspective of a past moment.','["A past fact","A current prediction","A future prediction from the perspective of a past moment.","A past regret"]','"Was going to be" = future-in-the-past: at that past moment, the exam lay ahead.','hard'),
  (cid,13,86,'gap_fill','The scientists announced that a new treatment ___ (would/launch) within two years. (future in the past)','would launch',NULL,'"Would + base verb" = future in the past in reported speech.','hard'),
  (cid,13,87,'multiple_choice','Which sentence expresses "future in the past" correctly?','The committee announced that results would be published the following month.','["The committee announced that results will be published the following month.","The committee announced that results would be published the following month.","The committee announced that results are going to be published the following month.","The committee announced that results were publishing the following month."]','"Would be published" = future in the past (will → would in reported/narrative past).','hard'),
  (cid,13,88,'gap_fill','She ___ ___ ___ (be/about/speak) when the fire alarm went off.','was about to speak',NULL,'"Was about to + base verb" = immediate future in the past (imminent action interrupted).','hard'),
  (cid,13,89,'multiple_choice','What does "The team was about to announce the breakthrough when the data error was discovered" mean?','The announcement was imminent but was prevented from happening.','["The announcement was made successfully","The announcement had already been made","The announcement was imminent but was prevented from happening.","The announcement happened, then the error was found"]','"Was about to + verb" = imminent past action that did not happen due to interruption.','hard'),
  (cid,13,90,'gap_fill','In 2010, experts predicted that renewable energy ___ (would/account) for 30% of the grid by 2030.','would account',NULL,'"Would account for" = future-in-the-past prediction made in 2010.','hard'),

  -- BLOCK 14: all future forms compared
  (cid,14,91,'multiple_choice','Which future form is BEST for a spontaneous decision made at the moment of speaking?','will','["going to","will","present continuous","future perfect"]','"Will" for spontaneous decisions. Going to = pre-planned. Present continuous = arranged.','medium'),
  (cid,14,92,'gap_fill','I already bought the tickets — I ___ (attend) the conference. (pre-planned)','am going to attend / am attending',NULL,'Going to = pre-planned decision. Present continuous = booked/arranged.','medium'),
  (cid,14,93,'multiple_choice','Rank the certainty of these future forms (most to least): "I will go / I''m going to go / I might go / I''m going."','I''m going > I''m going to go ≥ I will go > I might go','["I will go > I''m going to go > I''m going > I might go","I''m going > I''m going to go ≥ I will go > I might go","I might go > I will go > I''m going to go > I''m going","I will go = I''m going to go = I''m going = I might go"]','Present continuous (arrangement) ≈ going to (plan) > will (less certain, no evidence) > might (possibility).','hard'),
  (cid,14,94,'gap_fill','A: "Why are you looking so nervous?" B: "I ___ (go/present perfect evidence) to defend my thesis in an hour."','am going to',NULL,'Going to = imminent event with present evidence (nervous now).','medium'),
  (cid,14,95,'multiple_choice','Choose the BEST future form: "Look at the data — the correlation ___ be very strong."','is going to','["will","is going to","may","shall"]','"Is going to" for predictions based on visible/current evidence.','medium'),

  -- BLOCK 15: TOEFL Reading
  (cid,15,96,'multiple_choice','[TOEFL Reading] "Global food production is going to face unprecedented pressure as population growth and climate change converge." The use of "going to" suggests:','A prediction based on current trends and evidence already visible.','["A spontaneous decision about food production","An arranged future event","A prediction based on current trends and evidence already visible.","A formal obligation"]','Going to for evidence-based prediction: current trends visible now.','medium'),
  (cid,15,97,'gap_fill','[TOEFL Reading] "Researchers announced that the project ___ (would/expand) into three new countries by 2025." Reported prediction.','would expand',NULL,'"Would expand" = future in the past (reported speech).','hard'),
  (cid,15,98,'multiple_choice','[TOEFL Reading] "The city was about to implement the new traffic policy when protests forced a delay." This tells us:','The implementation was imminent but interrupted.','["The policy was implemented successfully","The protests occurred after implementation","The implementation was imminent but interrupted.","The protests caused the policy to be cancelled permanently"]','"Was about to implement" = imminent action in the past that was interrupted.','hard'),
  (cid,15,99,'gap_fill','[TOEFL Reading] "The team was going to use a double-blind design, but budget constraints forced a modification." This tells us?','The original plan was a double-blind design that was not carried out.','The team originally planned a double-blind design',NULL,'Was going to = unfulfilled past plan.','medium'),

  -- BLOCK 16: TOEFL Listening
  (cid,16,100,'multiple_choice','[TOEFL Listening] A professor says: "I''m meeting with the department chair this afternoon about the new research proposal." This implies:','The meeting is already arranged for today.','["The professor is having a meeting right now","The professor spontaneously decided to meet","The meeting is already arranged for today.","The professor is making an offer"]','Present continuous for confirmed future arrangement.','easy'),
  (cid,16,101,'gap_fill','[TOEFL Listening] "The professor mentioned she ___ (going to retire) at the end of the academic year but changed her mind." Past unfulfilled plan.','was going to retire',NULL,'"Was going to retire" = past plan that was not followed through.','medium'),
  (cid,16,102,'multiple_choice','[TOEFL Listening] "We were just about to leave when the fire alarm sounded." This means:','The departure was interrupted at the last moment.','["They left before the alarm","They left after the alarm","The departure was interrupted at the last moment.","They had already left when the alarm sounded"]','"Were about to leave when X happened" = imminent action interrupted.','medium'),

  -- BLOCK 17: TOEFL Speaking production
  (cid,17,103,'production','[TOEFL Speaking — 45s] Describe your plans for the next year using going to (pre-planned) and present continuous (arranged/scheduled). Include one was going to (unfulfilled past plan) for context.','',NULL,'I am going to focus on improving my academic English this year. I''m already enrolled in three online courses, and I''m taking the TOEFL in December. I was going to take it last year, but the test center closed unexpectedly. Now I am attending weekly tutoring sessions and I''m preparing a study plan.','medium'),
  (cid,17,104,'production','[TOEFL Speaking — 45s] A reading passage describes how scientists predicted climate change decades ago. Use: was going to, would, were about to, is going to, to describe both past predictions and current evidence.','',NULL,'In the 1970s, scientists predicted that global temperatures would rise by at least 2°C. The international community was about to sign a major climate agreement when oil price shocks changed political priorities. Years of unfulfilled commitments meant that emissions were going to continue unchecked. Now, data show that the worst-case scenario is going to become reality unless immediate action is taken.','hard'),

  -- BLOCK 18: TOEFL Writing production
  (cid,18,105,'production','[TOEFL Writing] Write 5 sentences about future developments in your field using: (1) going to (evidence-based prediction), (2) present continuous (arranged event), (3) will (certain prediction), (4) was going to (unfulfilled past plan), (5) would (future-in-the-past).','',NULL,'Based on current trends, AI is going to transform medical diagnostics within a decade. An international summit on AI ethics is taking place next month in Geneva. This shift will require significant retraining of healthcare professionals. The WHO was going to issue guidelines last year, but political disagreements caused delays. In 2019, analysts predicted that automated systems would account for 30% of diagnoses by 2025.','hard'),
  (cid,18,106,'production','[TOEFL Writing — Error Correction] Fix all future form errors: "She going to submit her paper tomorrow. The conference is go to start at 9 a.m. I was going to attend but I decided not going. They will to announce results soon. Are they going announce the winner?"','',NULL,'She is going to submit; is going to start (not ''go''); decided not to go; will announce (no ''to'' after ''will''); Are they going to announce.','hard'),
  (cid,18,107,'production','[TOEFL Writing — 150 words] Write a paragraph on "How is urban transportation going to change in the next 20 years?" Include at least 5 different future structures: going to, is/are + -ing, will, was going to (as historical context), and would (in a reported prediction). Underline each future structure.','',NULL,'Urban transportation is going to change dramatically over the next two decades. Autonomous vehicles are already entering limited public roadways, and they are likely to become mainstream by 2035. Several major cities are launching pilot programs for hyperloop transit next year. Analysts predicted in 2020 that electric vehicles would constitute over 50% of new car sales by 2030 — a target that now appears achievable. However, a global transition to public-private transportation networks was going to occur sooner, before supply chain issues and chip shortages slowed EV production. When infrastructure investment reaches critical mass, city planners will redesign street layouts to prioritize cyclists and pedestrians. By 2045, the privately owned car will likely be a minority choice in most major urban centers.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
